INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 20, 'theory', 'Квиз: бэкапы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 0, 'Что из перечисленного действительно является бэкапом?', '["Зеркало RAID 1 из двух дисков", "Снимок LVM в той же группе томов", "Ночная копия на другом сервере, из которой уже восстанавливались на тесте", "Реплика базы данных на соседнем хосте"]', 2, 'RAID переживает смерть диска, снимок гибнет вместе с группой томов, а реплика повторит и ошибочное удаление. Бэкап живёт отдельно от источника, и его восстановление проверено.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 1, 'Полная копия сделана в воскресенье, инкрементные по понедельникам–субботам. В четверг утром диск потерян. Что нужно для восстановления на среду?', '["Воскресная полная и инкрементные понедельника, вторника и среды", "Только копия среды", "Воскресная полная и копия среды", "Все копии за неделю, включая будущие"]', 0, 'Каждое приращение записывает изменения с предыдущей копии, поэтому нужна вся цепочка от последней полной. Разностная копия среды сократила бы цепочку до двух частей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 2, 'Команда rsync -a /srv/www /backup/ выполнена, в /srv/www лежит index.html. Где окажется файл?', '["/backup/index.html", "/srv/www/backup/index.html", "Команда завершится ошибкой без слэша в конце", "/backup/www/index.html"]', 3, 'Источник без слэша копируется вместе с каталогом под его именем. С записью /srv/www/ файл попал бы прямо в /backup.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 3, 'Что означает --keep-daily 7 в restic forget?', '["Все снимки за последние 7 календарных дней", "Самый свежий снимок в каждом из 7 последних дней, где снимки были", "Семь самых свежих снимков", "Удалить все снимки старше 7 дней"]', 1, 'Считаются только дни, в которых есть снимки; пустые дни пропускаются. Снимок, подошедший под любое другое правило, остаётся тоже.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 20, 4, 'Снимок LVM, созданный для бэкапа, заполнился на 100 процентов до конца копирования. Что произойдёт?', '["Исходный том остановится, пока вы не расширите снимок", "Старые блоки снимка тихо перезапишутся новыми", "Снимок станет недействительным, и копию придётся делать заново", "Снимок автоматически станет полной копией тома"]', 2, 'Исходный том продолжает работать, но снимок без места под изменённые блоки теряет согласованность и помечается недействительным (в lvs флаг I). Размер нужно считать заранее.');
